function pi_render_totals(frm) {
  const f = frm.fields_dict.custom_totals_html; if (!f) return;
  const d = frm.doc, cur = d.currency, fmt = v => format_currency(flt(v), cur);
  const key = [d.net_total, d.discount_amount, d.total_taxes_and_charges, d.grand_total, d.outstanding_amount].join('|');
  if (frm._pi_tot_key === key) return;
  frm._pi_tot_key = key;
  const due = d.docstatus === 1 ? d.outstanding_amount : d.grand_total;
  f.$wrapper.html(`<div class="pi-tot">
    <div class="pi-tot-row"><span>Discount</span><b>${fmt(d.discount_amount)}</b></div>
    <div class="pi-tot-row"><span>Untaxed Amount</span><b>${fmt(d.net_total)}</b></div>
    <div class="pi-tot-row"><span>PPN</span><b>${fmt(d.total_taxes_and_charges)}</b></div>
    <div class="pi-tot-row grand"><span>Total</span><b>${fmt(d.grand_total)}</b></div>
    <div class="pi-tot-row"><span>Amount Due</span><b>${fmt(due)}</b></div></div>`);
}

function pi_render_matrix_actions(frm) {
  const grid = frm.fields_dict.custom_approval_matrix && frm.fields_dict.custom_approval_matrix.grid;
  if (!grid || frm.doc.docstatus !== 1) return;
  const rows = (frm.doc.custom_approval_matrix || []).slice().sort((a, b) => (a.sequence || 0) - (b.sequence || 0));
  const active = rows.find(r => r.approval_status !== 'Approved');
  grid.wrapper.find('.pi-matrix-actions').remove();
  if (!active) return;
  const me = frappe.session.user;
  const eligible = (active.users || '').split(/[,\n]/).map(u => u.trim()).includes(me) ||
    (active.role && frappe.user_roles.includes(active.role)) ||
    frappe.user_roles.includes('System Manager');
  if (!eligible) return;
  const $bar = $(`<div class="pi-matrix-actions">
    <button class="btn btn-sm btn-primary pi-approve">${__('Approve Tier')} ${active.sequence || ''}</button>
    <button class="btn btn-sm btn-danger pi-reject">${__('Reject')}</button>
  </div>`);
  $bar.find('.pi-approve').on('click', () => pi_apply_action(frm, active, 'Approve'));
  $bar.find('.pi-reject').on('click', () => pi_apply_action(frm, active, 'Reject'));
  grid.wrapper.prepend($bar);
}

function pi_apply_action(frm, row, action) {
  const dialog = new frappe.ui.Dialog({
    title: __(action === 'Approve' ? 'Approve & Sign' : 'Reject'),
    fields: [{ fieldname: 'sig', fieldtype: 'Signature', label: __('Signature') }],
    primary_action_label: __(action),
    primary_action: (values) => {
      frappe.call({
        method: 'otobitz_integration.otobitz_integration.approval.apply_approval_action',
        args: { doctype: frm.doctype, docname: frm.doc.name, row_name: row.name, action, signature: values.sig },
        freeze: true,
      }).then(() => { dialog.hide(); frm.reload_doc(); });
    },
  });
  dialog.show();
}

frappe.ui.form.on('Purchase Invoice', {
  refresh(frm) {
    $(frm.wrapper).addClass('pi-hz'); $(document.body).addClass('full-width'); localStorage.container_fullwidth = 'true';
    frm.page.wrapper.find('.layout-side-section').hide();
    frm.page.wrapper.find('.layout-main-section-wrapper').css({ width: '100%', 'max-width': '100%', flex: '0 0 100%' });
    setTimeout(() => frm.toggle_display('company', true), 300); // erpnext.hide_company hides it with one company
    frm._pi_tot_key = null; pi_render_totals(frm);
    clearInterval(frm._pi_tot_t);
    // ponytail: poll because ERPNext sets totals without firing field events, same workaround as Sales Invoice / Purchase Order
    frm._pi_tot_t = setInterval(() => {
      if (cur_frm !== frm) return clearInterval(frm._pi_tot_t);
      pi_render_totals(frm);
      // Relabel grid to Odoo wording, force-show Subtotal like ERPNext hides it by default
      const g = frm.fields_dict.items && frm.fields_dict.items.grid, d = g && g.docfields.find(x => x.fieldname === 'net_amount');
      const L = { item_code: 'Product', description: 'Label', asset_category: 'Asset Categ.', expense_account: 'Account',
        cost_center: 'Analytic Acc.', custom_analytic_tags: 'Analytic Tags', qty: 'Quantity', uom: 'UoM',
        price_list_rate: 'Price', item_tax_template: 'Taxes', net_amount: 'Subtotal', amount: 'Total' };
      let dirty = false;
      if (g) Object.keys(L).forEach(f => { const x = g.docfields.find(y => y.fieldname === f); if (x && x.label !== L[f]) { x.label = L[f]; dirty = true; } });
      if (d && d.hidden) { g.set_column_disp('net_amount', true); dirty = true; }
      if (dirty) g.refresh();
    }, 400);
    pi_render_matrix_actions(frm);
    // keep only Odoo-like header buttons; ERPNext adds its own after our refresh, so clean up afterwards
    setTimeout(() => {
      if (cur_frm !== frm) return;
      frm.page.inner_toolbar.find('.inner-group-button').filter(function () {
        const l = decodeURIComponent($(this).attr('data-label') || '');
        return ['Tools', 'Status'].includes(l);
      }).remove();
    }, 600);
  },
  after_workflow_action(frm) {
    frm.reload_doc();
  },
  supplier(frm) {
    if (!frm.doc.supplier) { frm.set_value('custom_recipient_bank', ''); return; }
    frappe.db.get_value('Supplier', frm.doc.supplier, 'default_bank_account').then(r => {
      const acc = r.message && r.message.default_bank_account;
      if (!acc) return;
      frappe.db.get_value('Bank Account', acc, ['account', 'bank']).then(r2 => {
        const v = r2.message || {};
        if (v.account) frm.set_value('custom_recipient_bank', `${v.account}${v.bank ? ' - ' + v.bank : ''}`);
      });
    });
  },
});

frappe.ui.form.on('Purchase Invoice Item', {
  purchase_order(frm, cdt, cdn) {
    const row = frappe.get_doc(cdt, cdn);
    if (!row.purchase_order) return;
    frappe.db.get_value('Purchase Order', row.purchase_order, 'custom_sisa_uang_muka').then(r => {
      const v = r.message && r.message.custom_sisa_uang_muka;
      if (v !== undefined) frm.set_value('custom_sisa_uang_muka_display', v);
    });
  },
});

