/* si-num-fmt */
// ponytail: display-only grid shortening for Sales Invoice Item. Account shows code only. Drops "Rp", ",00", extra 3rd decimal zeros, " - PAO" company suffix, "Pajak Pertambahan Nilai" -> "PPN". Only visible text between tags is touched (data-name/href stay intact). Values and DB untouched.
(function () {
  const F = frappe.form.formatters, NUM = ['price_list_rate', 'net_amount', 'amount', 'custom_discount_value'], TXT = ['income_account', 'cost_center', 'item_tax_template'];
  const vis = (html, fn) => html.replace(/>([^<]+)</g, (m, t) => '>' + fn(t) + '<');
  const wrap = (t, fn) => { const o = F[t]; if (!o || o['_si_' + t]) return; F[t] = function (v, df) { const out = o.apply(this, arguments); return (df && df.parent === 'Sales Invoice Item' && typeof out === 'string') ? fn(out, df) : out; }; F[t]['_si_' + t] = 1; };
  ['Currency', 'Float'].forEach(t => wrap(t, (out, df) => NUM.includes(df.fieldname) ? vis(out, x => x.replace(/Rp\s*/g, '').replace(/(,\d\d)0+$/, '$1')) : out));
  wrap('Link', (out, df) => TXT.includes(df.fieldname) ? vis(out, x => x.replace(/\s-\s[A-Z]{2,5}$/, '').replace(/^(\d+\.\d+) - .*/, '$1').replace('(Inc) Pajak Pertambahan Nilai', 'PPN Inc')) : out);
  // Disc. column: "10%" when Discount Type is Percentage (display only)
  const fc = F.Float;
  F.Float = function (v, df, o, doc) { const out = fc.apply(this, arguments); return (df && df.parent === 'Sales Invoice Item' && df.fieldname === 'custom_discount_value' && doc && doc.custom_discount_type === 'Percentage' && typeof out === 'string') ? vis(out, x => x.replace(/,00$/, '') + '%') : out; };
  frappe.ui.form.on('Sales Invoice', { refresh(frm) { frm.fields_dict.items && frm.fields_dict.items.grid.refresh(); } });
})();

/* si-tax-dd */
// ponytail: display-only. Shortens the Tax dropdown rows ("(Inc) Pajak Pertambahan Nilai - PAO" -> "PPN Inc"). Awesomplete selects by its own data, not DOM text, so the saved value stays the full template name. Matches on the tax name text, so a new tax template needs its own rule.
(function () {
  if (window.__tax_dd) return; window.__tax_dd = 1;
  const short = t => t.replace(/\s-\s[A-Z]{2,5}$/, '').replace('(Inc) Pajak Pertambahan Nilai', 'PPN Inc').replace('(Excl) Pajak Pertambahan Nilai', 'PPN Excl');
  new MutationObserver(() => {
    document.querySelectorAll('.awesomplete ul p[title*="Pajak Pertambahan Nilai"]:not([data-short])').forEach(p => {
      p.dataset.short = 1;
      const s = p.querySelector('strong'); if (s) s.textContent = short(s.textContent);
      const sm = p.querySelector('.small'); if (sm) { sm.remove(); const br = p.querySelector('br'); br && br.remove(); }
    });
  }).observe(document.body, { childList: true, subtree: true });
})();

