/* si-item-cols */
// ponytail: display-only, mirrors Sales Order's so-item-cols. Product column
// shows the plain Item Code (erpnext core wires item_code's formatter to a
// "code: item_name" indicator pill elsewhere); Label column shows the
// Item's name instead of its own value. Saved item_code/description values
// are unchanged. See so-item-cols in Sales Order Full Width for why three
// separate caches (docfield_map, grid.docfields, docfield_copy) all have to
// be patched/cleared for this to actually stick on an already-rendered grid.
frappe.ui.form.on('Sales Invoice', {
  refresh(frm) {
    const grid = frm.fields_dict.items && frm.fields_dict.items.grid;
    if (!grid) return;

    const item_code_formatter = (value) => value || '';
    const description_formatter = (value, df, options, doc) => (doc && doc.item_name) || '';

    const map = frappe.meta.docfield_map['Sales Invoice Item'];
    if (map) {
      if (map.item_code) map.item_code.formatter = item_code_formatter;
      if (map.description) map.description.formatter = description_formatter;
    }
    (grid.docfields || []).forEach((df) => {
      if (df.fieldname === 'item_code') df.formatter = item_code_formatter;
      if (df.fieldname === 'description') df.formatter = description_formatter;
    });

    delete frappe.meta.docfield_copy['Sales Invoice Item'];
    grid.visible_columns = null;
    grid.grid_rows = null;
    grid.refresh();
  },
});

