// Short display names for Item Tax Template rows, e.g. "PPN Masukan - OTO"
// -> "PPN". Cached per template name (frappe.db.get_list is a server round
// trip; the grid formatter runs sync per cell, so this must be pre-fetched
// and read from cache, not awaited inline).
const _po_tax_label_cache = {};
// Match Odoo's exact wording for the two tax types this bench uses, from
// an account/tax-type name like "PPN Masukan - OTO" or "PPh 23 - OTO".
function po_account_tax_label(account_name) {
  const key = (account_name || '').split(' - ')[0];
  if (/^PPN /.test(key)) return 'Pajak Pertambahan Nilai';
  if (/^PPh /.test(key)) return key.replace(/^PPh /, 'Pajak Penghasilan Ps ');
  return key || account_name || 'Tax';
}

// Grid column is narrow - "PPN"/"PPh23" initials instead of the full name
// used in the totals widget below, which has room for it.
function po_account_tax_short(account_name) {
  const key = (account_name || '').split(' - ')[0];
  if (/^PPN /.test(key)) return 'PPN';
  const pph = key.match(/^PPh\s*(\S*)/);
  if (pph) return 'PPh' + (pph[1] || '');
  return key || 'Tax';
}

function po_item_tax_labels(template_name) {
  if (!template_name) return [];
  if (!_po_tax_label_cache[template_name]) {
    _po_tax_label_cache[template_name] = [template_name]; // fallback until loaded
    frappe.db.get_doc('Item Tax Template', template_name).then(doc => {
      _po_tax_label_cache[template_name] = (doc.taxes || []).map(t => po_account_tax_short(t.tax_type));
      if (cur_frm && cur_frm.doc.doctype === 'Purchase Order') cur_frm.fields_dict.items.grid.refresh();
    });
  }
  return _po_tax_label_cache[template_name];
}

function po_render_totals(frm) {
  const f = frm.fields_dict.custom_totals_html; if (!f) return;
  const d = frm.doc, cur = d.currency, fmt = v => format_currency(flt(v), cur);
  const discount = flt(d.discount_amount);
  const taxes = d.taxes || [];
  // Each tax row's amount is an unsigned magnitude; add_deduct_tax carries the
  // sign (ERPNext already nets it into total_taxes_and_charges/grand_total,
  // but the per-row display here has to apply the sign itself).
  const rows = taxes.map(t => {
    const sign = t.add_deduct_tax === 'Deduct' ? -1 : 1;
    const lbl = po_account_tax_label(t.account_head);
    return {lbl, amount: sign * flt(t.tax_amount)};
  });
  const key = [d.net_total, discount, d.total_taxes_and_charges, d.grand_total, JSON.stringify(rows)].join('|');
  if (frm._po_tot_key === key) return;
  frm._po_tot_key = key;
  const taxRows = rows.map(r => `<div class="po-tot-row"><span>${frappe.utils.escape_html(r.lbl)}</span><b>${fmt(r.amount)}</b></div>`).join('');
  f.$wrapper.html(`<div class="po-tot">
    <div class="po-tot-row"><span>Discount</span><b>${fmt(discount)}</b></div>
    <div class="po-tot-row"><span>Total (DPP)</span><b>${fmt(d.net_total)}</b></div>
    ${taxRows}
    <div class="po-tot-row grand"><span>Grand Total</span><b>${fmt(d.grand_total)}</b></div></div>`);
}


frappe.ui.form.on('Purchase Order', {
  refresh(frm) {
    $(frm.wrapper).addClass('po-hz'); $(document.body).addClass('full-width'); localStorage.container_fullwidth = 'true';
    frm.page.wrapper.find('.layout-side-section').hide();
    frm.page.wrapper.find('.layout-main-section-wrapper').css({width: '100%', 'max-width': '100%', flex: '0 0 100%'});
    setTimeout(() => frm.toggle_display('company', true), 300); // erpnext.hide_company hides it with one company
    frm._po_tot_key = null; po_render_totals(frm);
    clearInterval(frm._po_tot_t);
    // ponytail: poll because ERPNext sets totals without firing field events
    frm._po_tot_t = setInterval(() => {
      if (cur_frm !== frm) return clearInterval(frm._po_tot_t);
      po_render_totals(frm);
      // ERPNext hides Subtotal unless a discount / inclusive tax exists; Odoo always shows it
      const g = frm.fields_dict.items && frm.fields_dict.items.grid, d = g && g.docfields.find(x => x.fieldname === 'net_amount');
      // ERPNext re-appends "(IDR)" to currency labels; Odoo shows plain names
      const L = {price_list_rate: 'Price', net_amount: 'Subtotal', amount: 'Total'};
      let dirty = false;
      if (g) Object.keys(L).forEach(f => { const x = g.docfields.find(y => y.fieldname === f); if (x && x.label !== L[f]) { x.label = L[f]; dirty = true; } });
      if (d && d.hidden) { g.set_column_disp('net_amount', true); dirty = true; }
      if (dirty) g.refresh();
      // Odoo-style short tax badges: not every line is taxed (services vs
      // parts), so an empty template shows nothing. A template can bundle
      // more than one tax (PPN + PPh 23 in the same template), and Odoo
      // shows each as its own "(Excl) <name>" pill rather than one combined
      // label - po_item_tax_labels() below mirrors that. Link fieldtype
      // ignores df.formatter entirely (formatters.js Link() never calls
      // _apply_custom_formatter, unlike Data/Select), so this patches the
      // rendered .static-area directly instead - same DOM-poll approach
      // already used above for totals/labels on this 400ms tick.
      if (g) {
        g.grid_rows.forEach(row => {
          const col = row.columns && row.columns.item_tax_template;
          const v = row.doc && row.doc.item_tax_template;
          if (!col) return;
          const want = v ? `<span class="po-tax-pill">${frappe.utils.escape_html(po_item_tax_labels(v).join(' · '))}</span>` : '';
          if (col.static_area && col.static_area.html() !== want) col.static_area.html(want);
        });
      }
    }, 400);
    // Odoo shows Received/Billed only after confirmation
    const g = frm.fields_dict.items.grid, hide = frm.doc.docstatus === 0 ? 1 : 0;
    ['received_qty', 'custom_billed_qty'].forEach(f => g.update_docfield_property(f, 'hidden', hide));
    // keep only Odoo-like header buttons; ERPNext adds its own after our refresh, so clean up afterwards
    setTimeout(() => {
      if (cur_frm !== frm) return;
      frm.remove_custom_button('Update Items');
      ['Purchase Invoice', 'Payment Request'].forEach(b => frm.remove_custom_button(b, 'Create'));
      ['Hold', 'Close', 'Re-open'].forEach(b => frm.remove_custom_button(b, 'Status'));
      frm.page.inner_toolbar.find('.inner-group-button').filter(function () {
        const l = decodeURIComponent($(this).attr('data-label') || '');
        return ['Tools', 'Get Items From', 'Status'].includes(l);
      }).remove();
    }, 600);
    // display-only Billing Status (Odoo wording); assigned without set_value so the form is not marked dirty
    const bs = frm.doc.docstatus !== 1 ? 'Nothing to Bill' : (flt(frm.doc.per_billed) >= 100 ? 'Fully Billed' : 'Waiting Bills');
    if (frm.doc.custom_billing_status !== bs) { frm.doc.custom_billing_status = bs; frm.refresh_field('custom_billing_status'); }
    if (frm.doc.docstatus === 1 && flt(frm.doc.per_billed) < 100) {
      frm.add_custom_button(__('Create Bill'), () => frappe.model.open_mapped_doc({
        method: 'erpnext.buying.doctype.purchase_order.purchase_order.make_purchase_invoice', frm
      })).addClass('btn-primary');
    }
    // Odoo-style "Vendor Bills" smart button: a clickable count badge in the
    // header linking to the Purchase Invoices this PO billed. The sidebar
    // (where Frappe's native Connections count would normally show this) is
    // hidden above for the full-width layout, so this replaces it.
    if (frm.doc.docstatus === 1) {
      frappe.call({
        method: 'frappe.client.get_list',
        args: {doctype: 'Purchase Invoice Item', filters: {purchase_order: frm.doc.name}, fields: ['parent'], distinct: true, limit_page_length: 0},
      }).then(r => {
        const n = (r.message || []).length;
        if (!n) return;
        frm.add_custom_button(__('{0} Purchase Invoice{1}', [n, n > 1 ? 's' : '']), () =>
          frappe.set_route('List', 'Purchase Invoice', {purchase_order: frm.doc.name})
        );
      });
    }

    // po-item-cols: display-only, same fix as Sales Order's so-item-cols.
    // ponytail: Product column shows the plain Item Code; ERPNext core wires
    // item_code via frm.set_indicator_formatter to render "code: item_name"
    // as an indicator pill. That writes frappe.meta.docfield_map, but a grid
    // reads its OWN copy_dict() clone of each docfield (grid.docfields, made
    // once the first time the grid renders) - so docfield_map has to be
    // patched (a brand-new grid.docfields clone is copied from it), AND
    // grid.docfields itself has to be patched directly (this grid's clone
    // already exists by the time this runs). Two further caches sit
    // downstream and must be dropped too: GridRow reads through
    // frappe.meta.docfield_copy[doctype][docname] (its own per-document
    // clone, read once in its constructor) and render_result_rows() reuses
    // an existing GridRow instance (just .refresh()s it) for any doc it
    // already has a row for - so docfield_copy has to be cleared AND every
    // GridRow rebuilt from scratch. Description column shows the Item's
    // name instead of repeating the item code. Saved values (item_code/
    // description) are unchanged.
    if (frm.fields_dict.items && frm.fields_dict.items.grid) {
      const grid = frm.fields_dict.items.grid;
      const item_code_formatter = (value) => value || '';
      const description_formatter = (value, df, options, doc) => (doc && doc.item_name) || '';

      const map = frappe.meta.docfield_map['Purchase Order Item'];
      if (map) {
        if (map.item_code) map.item_code.formatter = item_code_formatter;
        if (map.description) map.description.formatter = description_formatter;
      }
      (grid.docfields || []).forEach((df) => {
        if (df.fieldname === 'item_code') df.formatter = item_code_formatter;
        if (df.fieldname === 'description') df.formatter = description_formatter;
      });

      delete frappe.meta.docfield_copy['Purchase Order Item'];
      grid.visible_columns = null;
      grid.grid_rows = null;
      grid.refresh();
    }
  },
  // Confirmation Date is now stamped server-side (otobitz_integration.purchase_order.track,
  // on the validate/before_update_after_submit hooks) - that fires on every
  // workflow_state transition regardless of how it was triggered (form click,
  // API, bulk action), unlike this client-only after_workflow_action used to.
  // The client hook is removed, not just left alongside the server one: both
  // writing to the same field on the same transition was a race (whichever
  // write landed last wins; the client one here saved an extra request too),
  // and the server hook alone already covers every case this used to.
  custom_purchase_rep(frm) {
    if (!frm.doc.custom_purchase_rep) { frm.set_value({custom_oi_employee: '', custom_oi_department: ''}); return; }
    frappe.db.get_value('Employee', {user_id: frm.doc.custom_purchase_rep}, ['name', 'department']).then(r => {
      const v = r.message || {}; frm.set_value({custom_oi_employee: v.name || '', custom_oi_department: v.department || ''});
    });
  },
  custom_oi_employee(frm) {
    // custom_otobitz_branch is hidden on this form (see field_order property
    // setter) but still required server-side - it drives PO naming
    // (set_branch_naming_series). Derive it from the Employee instead of
    // asking the user to pick it, same as Odoo keeps branch implicit.
    if (!frm.doc.custom_oi_employee) { frm.set_value({custom_oi_department: '', custom_otobitz_branch: ''}); return; }
    frappe.db.get_value('Employee', frm.doc.custom_oi_employee, ['department', 'branch']).then(r => {
      const v = r.message || {}; frm.set_value({custom_oi_department: v.department || '', custom_otobitz_branch: v.branch || ''});
    });
  },
  validate(frm) {
    const dd = frm.doc.schedule_date || frappe.datetime.get_today();
    (frm.doc.items || []).forEach(r => { if (!r.schedule_date) r.schedule_date = dd; });
    if (!frm.doc.schedule_date) frm.doc.schedule_date = dd;
  }
});
