// pe-summary: hint to Invoices tab + allocation summary (computed from rows; no extra fields)
function pe_summary(frm) {
  const draft = frm.doc.docstatus === 0, rows = (frm.doc.references || []).filter(r => r.reference_name);
  if (draft && frm.doc.party && !rows.length) {
    frm.set_intro(__('Select the invoices this payment settles in the {0} tab.', ['<a href="#" class="pe-go-inv"><b>Invoices</b></a>']), 'orange');
    $(frm.wrapper).find('.pe-go-inv').off('click').on('click', e => { e.preventDefault(); $(frm.wrapper).find('.form-tabs .nav-link').filter((i, el) => /Invoices/.test(el.innerText)).first().trigger('click'); });
  } else frm.set_intro('');
  const w = frm.fields_dict.references && frm.fields_dict.references.$wrapper; if (!w) return;
  w.find('.pe-alloc').remove();
  if (!rows.length && !frm.doc.party) return;
  const cur = frm.doc.paid_to_account_currency || frm.doc.paid_from_account_currency || frappe.defaults.get_default('currency');
  const total = rows.reduce((a, r) => a + flt(r.allocated_amount), 0), un = flt(frm.doc.paid_amount) - total, f = v => format_currency(v, cur);
  // ponytail: same-currency only (unallocated = Amount - allocated); multi-currency needs received_amount/exchange rate
  w.append(`<div class="pe-alloc" style="margin:10px 0 0 auto;width:min(360px,100%);background:#dbe4ef;border-radius:8px;padding:10px 14px;font-size:var(--text-md)">
    <div style="display:flex;justify-content:space-between"><span>${__('Total Allocated')}</span><b>${f(total)}</b></div>
    <div style="display:flex;justify-content:space-between;border-top:1px solid #b6c4d6;margin-top:6px;padding-top:6px"><span>${__('Unallocated Amount')}</span><b style="color:${Math.abs(un) > 0.005 ? 'var(--red-600)' : 'inherit'}">${f(un)}</b></div></div>`);
}
frappe.ui.form.on('Payment Entry', {
  party(frm) { pe_summary(frm); },
  paid_amount(frm) { pe_summary(frm); },
  onload(frm) {
    if (!frm.is_new()) return;
    if (!frm.doc.custom_otobitz_branch) frm.set_value('custom_otobitz_branch', 'HEAD OFFICE');
    // Odoo draft defaults: Journal Bank BCA, Payment Method Manual (only when not created from an invoice)
    if (!frm.doc.mode_of_payment) frm.set_value('mode_of_payment', 'Manual');
    if (!frm.doc.paid_to && frm.doc.payment_type !== 'Pay') frm.set_value('paid_to', 'Bank BCA - 6591000729 - PAO');
  },
  refresh(frm) {
    pe_summary(frm);
    $(frm.wrapper).addClass('so-hz'); $(document.body).addClass('full-width');
    // ponytail: Odoo shows Created on only after save; ERPNext creation is the equivalent
    if (!frm.is_new() && !frm.doc.custom_created_on) frm.doc.custom_created_on = frm.doc.creation;
    frm.page.wrapper.find('.layout-side-section').hide();
    frm.page.wrapper.find('.layout-main-section-wrapper').css({'width': '100%', 'max-width': 'none'});
    frm.toggle_display('naming_series', false);
    // smart buttons like Odoo ("1 Invoice", "Journal Entry")
    if (!frm.is_new() && frm.doc.docstatus === 1) {
      frm.dashboard.clear_headline();
      const n = (frm.doc.references || []).length;
      frm.dashboard.add_section(`<div class="pe-smart" style="display:flex;gap:8px;justify-content:flex-end">
        <a class="btn btn-default btn-sm" href="#" data-act="inv">${n} Invoice</a>
        <a class="btn btn-default btn-sm" href="/app/general-ledger?voucher_no=${encodeURIComponent(frm.doc.name)}" target="_blank">Journal Entry</a></div>`, '', 'pe-smart-sec');
      frm.dashboard.wrapper.find('[data-act=inv]').off('click').on('click', e => { e.preventDefault(); frm.scroll_to_field('references'); });
    }
    // ponytail: stock JS hides Memo until Custom Remarks is ticked; Odoo always shows it
    frm.toggle_display('remarks', true);
    frm.set_df_property('custom_created_on', 'hidden', frm.is_new() ? 1 : 0);
  },
  custom_is_internal_transfer(frm) {
    frm.set_value('payment_type', frm.doc.custom_is_internal_transfer ? 'Internal Transfer' : 'Receive');
  }
});

frappe.ui.form.on('Payment Entry Reference', {
  allocated_amount(frm) { pe_summary(frm); },
  reference_name(frm) { setTimeout(() => pe_summary(frm), 400); },
