// Same understated look as the Sales Invoice list (small-dot indicator,
// no colored background pill). The workflow state itself is literally
// named "Pending" (see PO Approval Workflow / Workflow State "Pending" -
// split off from the shared "Pending Approval" state so Purchase Invoice,
// which uses the same shared state, is unaffected). Frappe's list view
// renders the raw workflow state label directly (frappe.get_indicator in
// indicator.js takes the workflow branch whenever the Workflow has
// override_status unchecked, which this one does) - it does NOT call this
// get_indicator function for the main column, so no label remapping is
// needed here anymore. Kept only as a fallback for other views (Kanban,
// Report) that may still consult listview_settings.get_indicator directly.
frappe.listview_settings["Purchase Order"].add_fields = ["transaction_date", "workflow_state", "docstatus", "custom_confirmation_date", "schedule_date", "custom_source_document", "custom_billing_status"];
frappe.listview_settings["Purchase Order"].formatters = {
  // custom_confirmation_date is a Datetime field, so the raw value prints
  // with a "00:00:00" time component nobody set - date-only display, same
  // idea as the "Tanggal (Hari)" grouping label elsewhere.
  custom_confirmation_date(value) {
    if (!value) return "";
    return frappe.datetime.str_to_user(value).split(" ")[0];
