frappe.listview_settings["Sales Invoice"] = {
  add_fields: ["name", "customer", "custom_pph_amount", "customer_name", "posting_date", "due_date", "outstanding_amount", "grand_total", "currency", "status", "docstatus", "is_return"],

  // Odoo list: Number first, credit notes stay out of this menu.
  // ponytail: Frappe has one badge column. Status (Draft/Posted/Cancelled) uses it; Payment Status is drawn by a formatter on outstanding_amount. Odoo "In Payment" has no ERPNext equivalent, so it never shows.
  hide_name_column: true,
  // imogi_finance/public/js/list_view_columns.js patches EVERY List View in
  // Desk (not scoped to its own doctypes) and defaults settings.subject_field
  // to "name" when unset. Since this doctype's title_field is customer_name
  // (not "name"), that patch was swapping the subject column back to the raw
  // ID and re-inserting customer_name as a second, duplicate column (it's
  // in_list_view:0, so Frappe's own filtering never would have shown it on
  // its own) - declaring the subject field here as the same value this
  // listview_settings already relies on (the formatter below assumes the
  // subject IS customer_name) makes that patch's own fieldname check a
  // no-op, without touching imogi_finance's file.
  subject_field: "customer_name",
  filters: [["is_return", "=", 0]],
  formatters: {
    customer_name(v, df, doc) { return doc.name; },
    // Rp-prefixed like every other money column in the app (Sales Order list, forms); these were the one place showing bare numbers.
    net_total(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    grand_total(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    total_taxes_and_charges(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    custom_pph_amount(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
    posting_date(v) { return "<span>" + (v ? String(v).split("-").reverse().join("/") : "") + "</span>"; },
    due_date(v, df, doc) {
      if (!v || doc.docstatus != 1 || flt(doc.outstanding_amount) < flt(doc.grand_total)) return "<span></span>";
      var n = Math.round((new Date(v + "T00:00:00") - new Date(new Date().toDateString())) / 864e5), t, c = "";
      if (n === 0) { t = "Today"; c = "#b7791f"; } else if (n === -1) { t = "Yesterday"; c = "#c0392b"; }
      else if (n < 0) { t = (-n) + " days ago"; c = "#c0392b"; } else if (n === 1) t = "Tomorrow"; else t = "In " + n + " days";
      return '<span style="color:' + c + '">' + t + '</span>';
    },
    outstanding_amount(v, df, doc) {
      var o = flt(doc.outstanding_amount), g = flt(doc.grand_total), t = "Not Paid", c = "red";
      if (doc.docstatus == 1) { if (o <= 0) { t = "Paid"; c = "green"; } else if (o < g) { t = "Partially Paid"; c = "orange"; } }
      return '<span class="indicator-pill ' + c + ' ellipsis"><span class="ellipsis">' + t + '</span></span>';
    }
  },

  get_indicator(doc) {
    if (doc.docstatus == 2) return ["Cancelled", "red", "docstatus,=,2"];
    if (doc.docstatus == 0) return ["Draft", "blue", "docstatus,=,0"];
    return ["Posted", "green", "docstatus,=,1"];
  },
};

/* si-list-style */
// Tag column is empty for every row, so it is collapsed.
// Same look as the Sales Order list: blue header, "Number" label. Alignment:
// money columns right, date/status-ish columns left, everything else center.
// ponytail: nth-child ties widths to column order (1 Number, 2 Tag, 3 Customer, 4 Invoice Date, 5 Due Date, 6 Tax Number, 7 Tax Excluded, 8 Total, 9 Payment Status, 10 Total PPN, 11 Total PPh, 12 Status). Update if columns move.
// si-no-dup-currency: "Total in Currency" (base_grand_total) dropped - this shop is IDR-only (one Company,
// no multi-currency sales), so it was always identical to Total and just ate space the user has to scroll for.
// si-order-fix: imogi_finance's global custom.css sets `order` on .list-row-col:nth-child(2..7) for every
// list view site-wide (no page scoping), which visually scrambles column order here (Total/Payment Status
// jump before Customer/Invoice Date). `[data-page-route=...] .frappe-list .list-row-head .level-left >` has
// higher specificity than imogi's bare `.list-row-head .list-row-col`, so resetting order here wins without
// touching that other app's file.
