// ═══════════════════════════════════════════════════════════
// Sales Order — List View Client Script
// Combined: Group By + Left ID Inject + Business Status
// PT. Inovasi Terbaik Bangsa
// ═══════════════════════════════════════════════════════════

frappe.listview_settings["Sales Order"] = {
  add_fields: ["name", "transaction_date", "customer", "custom_payment_status", "per_billed", "docstatus"],

  get_indicator(doc) {
    const status = get_so_business_status(doc);
    // 3rd element is a filter route: click the pill to filter the list by that status (native Frappe behavior)
    const status_map = {
      "Draft":          ["Draft",          "grey",       "docstatus,=,0"],
      "To Invoice":     ["To Invoice",     "light-blue", "docstatus,=,1|per_billed,<,100"],
      "Fully Invoiced": ["Fully Invoiced", "green",      "docstatus,=,1|per_billed,>=,100"],
      "Cancelled":      ["Cancelled",      "red",        "docstatus,=,2"],
    };
    return status_map[status] || [status, "grey"];
  },

  formatters: {
    custom_salesperson(value) {
      // ponytail: display only; stored value stays the user id (email)
      return value
        ? `<span>${frappe.utils.escape_html(String(value).split("@")[0])}</span>`
        : '<span class="text-muted">–</span>';
    },
    custom_payment_status(value, df, doc) {
      const status = get_so_business_status(doc);
      const color = get_so_status_color(status);
      const icon_map = {};
      return `<span class="indicator-pill ${color} ellipsis">${icon_map[status] || ""} ${frappe.utils.escape_html(status)}</span>`;
    },
    custom_otobitz_so_number(value) {
      return value ? frappe.utils.escape_html(value) : '<span class="text-muted">–</span>';
    },
    custom_otobitz_faktur_number(value) {
      return value ? frappe.utils.escape_html(value) : '<span class="text-muted">–</span>';
    }
  },
};

