// so-odoo-status: Odoo invoice_status wording. ponytail: ignores Paid/Partial Paid (Odoo list does too); add a Payment Status column if needed.
function get_so_business_status(doc) {
  if (cint_so(doc.docstatus) === 2) return "Cancelled";
  if (cint_so(doc.docstatus) === 0) return "Draft";
  return parseFloat(doc.per_billed || 0) >= 100 ? "Fully Invoiced" : "To Invoice";
}

function get_so_status_color(status) {
  return {"Draft": "grey", "To Invoice": "light-blue", "Fully Invoiced": "green", "Cancelled": "red"}[status] || "grey";
}

function cint_so(v) { return parseInt(v || 0, 10); }

