/* so-item-cols */
// ponytail: display-only. Product column shows the plain Item Code; the
// erpnext core Sales Order setup() wires item_code via
// frm.set_indicator_formatter (sales_order.js) to render "code: item_name"
// as an indicator pill. That writes frappe.meta.docfield_map, but a grid
// reads its OWN copy_dict() clone of each docfield (grid.docfields, made
// once the first time the grid renders) - so docfield_map has to be
// patched (because a brand-new grid.docfields clone is copied from it),
// AND grid.docfields itself has to be patched directly (because this
// grid's clone already exists by the time this runs). Two further caches
// sit downstream of grid.docfields and must be dropped too: GridRow reads
// through frappe.meta.docfield_copy[doctype][docname] (its own per-document
// clone, read once in its constructor) and render_result_rows() reuses an
// existing GridRow instance (just .refresh()s it) for any doc it already
// has a row for - so docfield_copy has to be cleared AND every GridRow
// rebuilt from scratch. Description column shows the Item's name instead
// of its (usually empty) long description. Saved values (item_code/
// description) are unchanged.
frappe.ui.form.on('Sales Order', {
  refresh(frm) {
    const grid = frm.fields_dict.items && frm.fields_dict.items.grid;
    if (!grid) return;

    const item_code_formatter = (value) => value || '';
    const description_formatter = (value, df, options, doc) => (doc && doc.item_name) || '';

    const map = frappe.meta.docfield_map['Sales Order Item'];
    if (map) {
      if (map.item_code) map.item_code.formatter = item_code_formatter;
      if (map.description) map.description.formatter = description_formatter;
    }
    (grid.docfields || []).forEach((df) => {
      if (df.fieldname === 'item_code') df.formatter = item_code_formatter;
      if (df.fieldname === 'description') df.formatter = description_formatter;
    });

    // GridRow caches its docfields per-ROW (keyed by the child row's own
    // .name, not the parent Sales Order's) via frappe.meta.docfield_copy -
    // clearing the whole doctype entry (every row's cached copy), not one
    // key, is what actually forces a rebuild from the patched source above.
    delete frappe.meta.docfield_copy['Sales Order Item'];
    grid.visible_columns = null;
    grid.grid_rows = null;
    grid.refresh();
  },
});

