(function () {
  var _prev_settings = frappe.listview_settings["Purchase Invoice"] || {};
  var _prev_onload = _prev_settings.onload;

  frappe.listview_settings["Purchase Invoice"] = Object.assign({}, _prev_settings, {
    add_fields: (_prev_settings.add_fields || []).concat(["name", "supplier", "supplier_name", "posting_date", "due_date", "bill_no", "tax_id", "net_total", "grand_total", "total_taxes_and_charges", "taxes_and_charges_deducted", "outstanding_amount", "currency", "is_return", "creation"]),

    // Odoo "Bills" list: Number first, credit notes stay out of this menu.
    hide_name_column: true,
    filters: [["is_return", "=", 0]],

    formatters: Object.assign({}, _prev_settings.formatters, {
      supplier_name(v, df, doc) { return doc.name; },
      net_total(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
      grand_total(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
      total_taxes_and_charges(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
      taxes_and_charges_deducted(v, df, doc) { return "<span>" + format_currency(v, doc.currency, 2) + "</span>"; },
      posting_date(v) { return "<span>" + (v ? String(v).split("-").reverse().join("/") : "") + "</span>"; },
      due_date(v, df, doc) {
        if (!v || doc.docstatus == 2 || (doc.docstatus == 1 && flt(doc.outstanding_amount) <= 0)) return "<span></span>";
        var n = Math.round((new Date(v + "T00:00:00") - new Date(new Date().toDateString())) / 864e5), t, c = "";
        if (n === 0) { t = "Today"; c = "#b7791f"; } else if (n === -1) { t = "Yesterday"; c = "#c0392b"; }
        else if (n < 0) { t = (-n) + " days ago"; c = "#c0392b"; } else if (n === 1) t = "Tomorrow"; else t = "In " + n + " days";
        return '<span style="color:' + c + '">' + t + '</span>';
      },
      // pi-short-creation: default Datetime formatter prints seconds + locale time
      // which doesn't fit a tight list column; match the DD/MM/YYYY HH:mm style
      // already used by posting_date so the row stays one line.
      creation(v) {
        if (!v) return "<span></span>";
        var d = new Date(String(v).replace(" ", "T"));
        var pad = (n) => String(n).padStart(2, "0");
        return "<span>" + pad(d.getDate()) + "/" + pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + pad(d.getHours()) + ":" + pad(d.getMinutes()) + "</span>";
      },
    }),

    onload: function (listview) {
      if (_prev_onload) { _prev_onload(listview); }

      // pi-created-on: "creation" is a standard meta field, not a DocField, so it can
      // never be added via List View Settings -> in_list_view (no DocField exists to flag).
      // Push it as a synthetic Field column instead; render_list() re-reads
      // listview.columns on every refresh, so this survives sort/filter/pagination.
      if (!listview.columns.some((c) => c.df && c.df.fieldname === "creation")) {
        listview.columns.push({
          type: "Field",
          df: {
            label: __("Created on"),
            fieldname: "creation",
            fieldtype: "Datetime",
          },
        });
      }

      if (frappe.model.can_create("Payment Entry")) {
        listview.page.add_action_item(__("Payment"), () => {
          erpnext.bulk_transaction_processing.create(listview, "Purchase Invoice", "Payment Entry");
        });
      }
      if (frappe.model.can_create("Purchase Receipt")) {
        listview.page.add_action_item(__("Purchase Receipt"), () => {
          erpnext.bulk_transaction_processing.create(listview, "Purchase Invoice", "Purchase Receipt");
        });
      }
    },
  });
})();

/* pi-list-style */
// Same look as the Purchase Order / Sales Invoice lists: blue header,
// centered dates/status, money right-aligned.
// pi-head-match: background/alignment rules below must hit .list-row-head too,
// not just .list-row -- otherwise the header looks unstyled next to the data rows.
// pi-order-fix: imogi_finance's global custom.css sets `order` on
// .list-row-col:nth-child(2..7) for every list view site-wide (no page scoping),
// which would otherwise scramble the column order here. The page-route-scoped
// selector below has higher specificity, so resetting order per column wins
// without touching that other app's file (same fix as the Sales Invoice list).
// pi-fixed-width-v2: tried letting Frappe's native width engine (apply_column_widths)
// size every column automatically -- it only measures each column's DATA value, never
// its header LABEL, so a column like "Total PPh" (short data "Rp 0,00" but a 9-char
// label) got sized too narrow and the label text overflowed into "Status". It also
// completely skips the Status column (type "Status" has no data-fieldname, so the
// engine's data-fieldname selector never matches it), so Status never got a real width
// at all. Back to explicit widths, this time sized from MAX(header label length, real
// data length) checked against actual DB values -- not guessed from a screenshot.
// Every non-subject/non-Vendor column also gets ellipsis as a safety net: if a width
// is still slightly off for some edge-case value, text truncates instead of overlapping
// the next column.
(function () {
  if (document.getElementById("pi-list-style")) return;
  const R = '[data-page-route="List/Purchase Invoice/List"] ', st = document.createElement("style"); st.id = "pi-list-style";
  // 1 Number(ID), 2 Tag, 3 Vendor, 4 Bill Date, 5 Due Date, 6 Reference, 7 Tax Number,
  // 8 Tax Excluded, 9 Total, 10 Total PPN, 11 Total PPh, 12 Status, 13 Created on
  // Widths = max(header label width, real column data width) + padding, verified against
  // actual DB values (longest supplier/bill_no/status/etc.), not guesswork.
  const WIDTH = {
    4: '96px',   // "Bill Date" label / "23/10/2026"
    5: '96px',   // "Due Date" label / "23 days ago"
    6: '130px',  // "Bill Reference" label (14ch) / "BILL-107-P00011" (15ch)
    7: '96px',   // "Tax Number" label (always empty in data today)
    8: '140px',  // "Tax Excluded" / "Rp 8.600.000,00"
    9: '140px',  // "Grand Total" / "Rp 8.600.000,00"
    10: '120px', // "Total PPN" / "Rp 112.500,00"
    11: '120px', // "Total PPh" label (9ch) -- this is the column that broke before
    12: '150px', // Status -- "Pending Approval" (16ch) is the longest real workflow state
    13: '150px', // "Created on" / "23/10/2026 20:18"
  };
  const CENTER = ['posting_date', 'due_date', 'creation'];
  const RIGHT = ['net_total', 'grand_total', 'total_taxes_and_charges', 'taxes_and_charges_deducted'];
  let css =
    // pi-no-gap: the base .list-row-col rule has `margin-right: 15px` -- that gap is
    // transparent, so with a colored header background it showed up as little white
    // boxes between/under each column label. Zeroing the margin on the header row
    // (and painting the column itself, not just the text spans inside it) closes it.
    R + '.list-row-head,' + R + '.list-row-head .list-row-col,' + R + '.list-row-head .level-item,' + R + '.list-row-head .level-right{background-color:#dbe4ef !important}' +
    R + '.list-row-head .list-row-col{margin-right:0 !important}' +
    R + '.list-row-head{min-height:40px !important;align-items:flex-start !important;padding-top:8px !important;padding-bottom:8px !important}' +
    // pi-row-min-width: sum of every fixed column width above (~1680px) + per-column
    // padding. Setting this on the row itself (not just relying on the columns' own
    // widths) stops flexbox from trying to compress the row's children to fit a narrower
    // container -- below this width the row simply doesn't shrink, and the scrollbar
    // that .result-container already provides (core list.scss) takes over instead.
    R + '.list-row-container .list-row,' + R + '.list-row-head{min-width:1800px !important}' +
    R + '.list-row-container .list-row > .level-right,' + R + '.list-row-head > .level-right{display:none !important}' +
    R + '.list-row-container .list-row > .level-left,' + R + '.list-row-head > .level-left{flex:1 1 auto !important;width:100% !important}' +
    // pi-no-min-floor: base .list-row-col CSS sets min-width:150px on every column,
    // which fights our explicit per-column widths below (flexbox can't shrink under
    // min-width). Removing the floor so our widths actually apply.
    R + '.list-row-col{box-sizing:border-box;min-width:0 !important;max-width:none !important;margin-right:0 !important;padding-right:8px !important}' +
    // pi-no-squeeze: Number and Vendor used to be allowed to shrink (flex-shrink:1) so
    // they'd absorb space pressure instead of the row overflowing. At some zoom levels /
    // window widths that squeeze went too far -- both columns got compressed down near 0,
    // so "Number" text visually ran into "Vendor" text with almost no gap, even though
    // they're still two separate cells. Fixed, non-shrinking width for every column
    // (Number and Vendor included) removes that failure mode entirely: a column is either
    // its full intended width, or the row doesn't fit and the already-present horizontal
    // scrollbar (.result-container{overflow-x:auto} in core list.scss) kicks in. Never
    // squeezed, never overlapping.
    R + '.list-row .list-subject.level,' + R + '.list-row-head .list-subject.level{min-width:0 !important;width:220px !important;flex:0 0 220px !important}' +
    R + '.list-row-container .list-row .list-subject .level-item,' + R + '.list-row-head .list-subject .level-item{min-width:0 !important;overflow:hidden !important}' +
    R + '.list-row-container .list-row .list-subject a{font-weight:600 !important;display:inline-block !important;max-width:100% !important;overflow:hidden !important;text-overflow:ellipsis !important;white-space:nowrap !important;vertical-align:bottom !important}' +
    // Vendor (col 3): fixed width, truncates with "..." if a supplier name is longer.
    R + '.list-row-container .list-row .level-left > .list-row-col:nth-child(3),' + R + '.list-row-head .level-left > .list-row-col:nth-child(3){flex:0 0 220px !important;width:220px !important;min-width:0 !important;white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}' +
    R + '.list-row-container .list-row .level-left,' + R + '.list-row-head .level-left{align-items:stretch !important}' +
    R + '.list-row-container .list-row .level-left > .list-row-col:not(.hide){display:flex !important;align-items:center}' +
    R + '.list-row-head .level-left > .list-row-col:not(.hide){display:flex !important;align-items:flex-start !important}' +
    // header labels may wrap to 2 lines so a long label doesn't force the column wider than its data needs
    R + '.list-row-head .list-row-col{white-space:normal !important;overflow:visible !important;text-overflow:clip !important;line-height:1.25;font-size:12px}' +
    // body cells (every column except Vendor, handled above) stay single-line with ellipsis
    // as a safety net -- a width slightly too tight truncates instead of overlapping the next column.
    R + '.list-row-container .list-row .level-left > .list-row-col:not(.list-subject):not(.tag-col):nth-child(n+4){white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}';
  for (let i = 1; i <= 13; i++) {
    ['.list-row-container .list-row', '.list-row-head'].forEach((r) => {
      css += R + r + ' .level-left > .list-row-col:nth-child(' + i + '){order:' + i + ' !important}';
      // pi-fixed-no-grow-no-shrink: every column (including Number/Vendor, set above) is a
      // hard fixed width now -- flex-grow 0, flex-shrink 0. Earlier versions let columns
      // grow to fill empty space or shrink to fit a tight window; both caused bugs (dead
      // whitespace vs. clipped/overlapping text at different window widths and zoom
      // levels). A completely rigid row is the one layout that can't misrender: at any
      // zoom/width it's either shown at full size or the row's native horizontal
      // scrollbar appears, exactly as asked for.
      if (WIDTH[i]) css += R + r + ' .level-left > .list-row-col:nth-child(' + i + '){flex:0 0 ' + WIDTH[i] + ' !important;width:' + WIDTH[i] + ' !important}';
    });
  }
  RIGHT.forEach(f => { css += R + '.list-row-container .list-row .level-left > .list-row-col[data-fieldname="' + f + '"],' + R + '.list-row-head .level-left > .list-row-col[data-fieldname="' + f + '"]{justify-content:flex-end !important;text-align:right}'; });
  CENTER.forEach(f => { css += R + '.list-row-container .list-row .level-left > .list-row-col[data-fieldname="' + f + '"],' + R + '.list-row-head .level-left > .list-row-col[data-fieldname="' + f + '"]{justify-content:center !important;text-align:center !important}'; });
  // Status is a "Status" type column, not a Field, so it carries no data-fieldname -- target by position (col 12)
  css += R + '.list-row-container .list-row .level-left > .list-row-col:nth-child(12),' + R + '.list-row-head .level-left > .list-row-col:nth-child(12){justify-content:center !important;text-align:center !important}';
  st.textContent = css;
  document.head.appendChild(st);
  const fix = () => document.querySelectorAll(R + '.list-row-head .list-subject span').forEach(e => { if (!e.children.length && /^(Supplier Name|ID)$/.test(e.textContent.trim())) e.textContent = 'Number'; });
  new MutationObserver(fix).observe(document.body, {childList: true, subtree: true});
})();

// Payment Entry's own List View, reordered to: ID, Date, Title, Payment
// Type, Journal, Payment Method, Party, Amount, Status - the user's
// requested left-to-right order, which native Frappe can't produce on its
// own (the Subject/title column is always hard-coded to the DOM's first
// position, and the Status indicator column has no fieldname to target via
// List View Settings' own field-order mechanism).
//
// Done via CSS flexbox `order` (not DOM reordering) keyed by data-fieldname
// - same mechanism, same reasoning, as the old order-reset version of this
// script: imogi_finance/public/css/custom.css ships a global (unscoped)
// `.list-row-col:nth-child(N){order:...}` rule for EVERY List View in the
// whole Desk, assuming a fixed column count/position it was written for.
// On this doctype that stale rule reshuffled the visual order away from
// whatever's set here, so it must be overridden at the same selector
// specificity, scoped to this route only - not touching imogi_finance's
// file or its own list views.
//
// The Status column carries no data-fieldname at all (unlike every other
// column here) - frappe/public/js/frappe/list/list_view.js's own
// setup_columns() renders it as `{type: "Status"}` with no `df`. It's
// targeted here by exclusion instead: the only two list-row-col elements
// without a data-fieldname are this Status column and the (always-hidden)
// Tag column, and only Status lacks the tag-col class.
//
// ID column also gets an explicit wider fixed width: native flex-basis
// here (Frappe divides available width evenly-ish across however many
// in_list_view fields exist) gave it ~138px, short of what
// "ACC-PAY-2026-00008"'s own rendered text (~155px) PLUS the select-all
// checkbox moved into this column below (~30px) both need together.
// flex: 0 0 220px (no grow, no shrink) keeps it at that width regardless
// of viewport/other-column changes, instead of a flex-basis number that's
// only correct for today's exact ID format/length.
(function () {
  if (document.getElementById("pe-list-order-fix")) return;
  var R = '[data-page-route="List/Payment Entry/List"] ', st = document.createElement("style");
  st.id = "pe-list-order-fix";
  var ORDER = {
    name: 1,
    posting_date: 2,
    title: 3,
    payment_type: 4,
    paid_to: 5,
    mode_of_payment: 6,
    party: 7,
    paid_amount: 8,
  };
  var css = "";
  Object.keys(ORDER).forEach(function (fieldname) {
    css += R + '.list-row-head .list-row-col[data-fieldname="' + fieldname + '"], ' +
      R + '.list-row .list-row-col[data-fieldname="' + fieldname + '"]{order:' + ORDER[fieldname] + ' !important}';
  });
  css += R + '.list-row-head .list-row-col:not([data-fieldname]):not(.tag-col), ' +
    R + '.list-row .list-row-col:not([data-fieldname]):not(.tag-col){order:9 !important}';
  css += R + '.list-row-head .list-row-col[data-fieldname="name"], ' +
    R + '.list-row .list-row-col[data-fieldname="name"]{flex:0 0 220px !important;width:220px !important;display:flex !important;align-items:center !important}';
  st.textContent = css;
  document.head.appendChild(st);
})();

// The select-all / row-select checkbox is hard-coded by Frappe's own
// get_header_html()/get_left_html() as a child of the Subject (Title)
// column specifically (frappe/public/js/frappe/list/list_view.js) - moving
// the ID column visually in front of Title via CSS `order` above doesn't
// touch the DOM, so the checkbox stayed with Title instead of following to
// the new first position. Relocated here into the ID column's own DOM node
// instead (one span.select-like moved per header/row, not rebuilt) so
// native click/shift-select/select-all handlers - which bind by class, not
// by which column the element happens to sit in - keep working unchanged.
// Runs after every header/row (re)render via MutationObserver rather than
// patching render_header()/get_left_html() directly, matching this app's
// existing so-number-head pattern for the same kind of post-render DOM tweak.
(function () {
  if (document.getElementById("pe-checkbox-move-marker")) return;
  var marker = document.createElement("meta");
  marker.id = "pe-checkbox-move-marker";
  document.head.appendChild(marker);

  function moveCheckbox(titleCol) {
    if (!titleCol || titleCol.getAttribute("data-fieldname") !== "title") return;
    var checkboxSpan = titleCol.querySelector(":scope > .select-like");
    if (!checkboxSpan) return;
    var row = titleCol.closest(".list-row-head, .list-row");
    if (!row) return;
    var idCol = row.querySelector('.list-row-col[data-fieldname="name"]');
    if (!idCol || idCol.querySelector(".select-like")) return;
    idCol.prepend(checkboxSpan);
  }

  function fix() {
    document
      .querySelectorAll('[data-page-route="List/Payment Entry/List"] .list-row-col[data-fieldname="title"]')
      .forEach(moveCheckbox);
  }

  fix();
  new MutationObserver(fix).observe(document.body, { childList: true, subtree: true });
})();

// ════════════════════════════════════════════════════════════════════
// CONFIGURE COLUMNS (Order Lines) - dropdown inline ala Odoo
//
// Frappe punya fitur bawaan setara (gear icon di header grid -> modal
// dialog "Configure Columns"), tapi tampilannya dibikin dropdown inline
// nempel di gear, bukan modal - jadi gear bawaan di-retarget ke
// dropdown kustom ini, bukan dibikin tombol baru.
//
// Hanya 3 kolom yang benar2 opsional (field ini di Sales Order Item punya
// in_list_view=0 secara default):
//   - Allowed Vendor (fieldname: supplier)
//   - Route (fieldname: custom_route)
//   - Lead Time (fieldname: custom_lead_time)
// 12 kolom lainnya (Product, Description, Cost Center, Disc. Type, Disc.,
// Qty, Delivered, Invoiced, UoM, Price, Tax, Total) sudah wajib tampil
// lewat in_list_view=1 di meta sendiri - script ini sama sekali tidak
// menyentuhnya, cuma mengatur 3 kolom opsional di atas.
//
// Preference disimpan per-browser di localStorage, bukan di User Settings
// server-side milik Frappe - grid.set_column_disp_in_list_view() sendiri
// cuma grid-local in-memory, jadi tanpa localStorage pilihan akan hilang
// tiap reload.
// ════════════════════════════════════════════════════════════════════

frappe.ui.form.on("Sales Order", {
    refresh(frm) {
        setup_order_lines_column_picker(frm);
        // Toolbar/grid can render asynchronously in different phases.
        [250, 700, 1400].forEach((ms) => {
            setTimeout(() => setup_order_lines_column_picker(frm), ms);
        });
    },
});

const ORDER_LINES_OPTIONAL_COLUMNS = [
    { fieldname: "supplier", label: "Allowed Vendor" },
    { fieldname: "custom_route", label: "Route" },
    { fieldname: "custom_lead_time", label: "Lead Time" },
];
// Preference stores the SHOWN optional fieldnames (opt-in), not hidden ones
// - these 3 columns default to off, so "nothing saved yet" must mean
// "nothing shown", the inverse of an all-shown-by-default list.
const ORDER_LINES_COLUMNS_STORAGE_KEY = "imogi_so_items_shown_optional_columns";

if (!document.getElementById("so-col-picker-style")) {
    const s = document.createElement("style");
    s.id = "so-col-picker-style";
    // `position:fixed` (not `absolute` nested under the gear) because the
    // gear's own cell (`.col.grid-static-col.pointer`) - and a couple of its
    // ancestors (`.form-grid`, `.form-grid-container`) - carry Frappe's own
    // `overflow:hidden`. A dropdown appended inside the gear cell as
    // `absolute` is clipped to that ~30x32px cell and never visibly escapes
    // it, even though it's technically present and "visible" in the DOM.
    // Appending to `<body>` with `fixed` positioning (top/left computed from
    // the gear's `getBoundingClientRect()` in JS) sidesteps every one of
    // those ancestor clips.
    s.textContent = "#so-col-dd{display:none;position:fixed;background:var(--fg-color,#fff);border:1px solid var(--border-color,#d1d8dd);border-radius:8px;min-width:200px;max-height:320px;overflow-y:auto;z-index:9999;padding:6px 0;box-shadow:var(--shadow-lg,0 4px 16px rgba(0,0,0,.12))}"
        + "#so-col-dd.is-open{display:block}"
        + ".so-col-opt{display:flex;align-items:center;gap:8px;padding:7px 12px;cursor:pointer;font-size:13px;color:#36414c}"
        + ".so-col-opt:hover{background:#f5f7fa}"
        + ".so-col-opt input{margin:0}";
    document.head.appendChild(s);
}

function get_shown_order_lines_columns() {
    try {
        return JSON.parse(localStorage.getItem(ORDER_LINES_COLUMNS_STORAGE_KEY) || "[]");
    } catch (e) {
        return [];
    }
}

function save_shown_order_lines_columns(shown) {
    try {
        localStorage.setItem(ORDER_LINES_COLUMNS_STORAGE_KEY, JSON.stringify(shown));
    } catch (e) {
        // private window / storage blocked - picker still works for this
        // page load, it just won't persist across reloads.
    }
}

function apply_order_lines_column_visibility(grid, shown) {
    const shown_set = new Set(shown);
    const shown_fieldnames = ORDER_LINES_OPTIONAL_COLUMNS.filter((col) => shown_set.has(col.fieldname)).map((col) => col.fieldname);
    const hidden_fieldnames = ORDER_LINES_OPTIONAL_COLUMNS.filter((col) => !shown_set.has(col.fieldname)).map((col) => col.fieldname);
    // `set_column_disp_in_list_view` accepts an array of fieldnames - one
    // call per show/hide group instead of 3 separate calls, so only one
    // `debounced_refresh()` gets scheduled per visibility change.
    if (shown_fieldnames.length) grid.set_column_disp_in_list_view(shown_fieldnames, true);
    if (hidden_fieldnames.length) grid.set_column_disp_in_list_view(hidden_fieldnames, false);
}

function setup_order_lines_column_picker(frm) {
    const grid_field = frm.fields_dict?.items;
    const grid = grid_field?.grid;
    if (!grid || !grid.wrapper || grid.__so_col_picker_patched) return;
    grid.__so_col_picker_patched = true;

    // `make_head()` tears down and recreates the header `.grid-row` (and its
    // gear button) on every `grid.refresh()` - not just the initial render,
    // but also after add/remove row, since those call the same debounced
    // refresh. Patching `make_head` itself (once, on the grid instance)
    // instead of binding to today's gear element is what keeps the dropdown
    // wired up across all of those rebuilds, rather than only working until
    // the first row is added.
    //
    // Deliberately NOT re-applying column visibility here on every
    // make_head() call: `set_column_disp_in_list_view()` itself schedules
    // another `debounced_refresh()` (-> another `refresh()` -> another
    // `make_head()`), so doing that unconditionally on every make_head would
    // be an infinite refresh loop. It isn't needed anyway - once set, the
    // hidden fieldnames live in `grid.column_disp_overrides`, which
    // `setup_fields()` (called by every `refresh()`, before `make_head()`)
    // already re-applies to the grid's docfields every single refresh on
    // its own.
    const original_make_head = grid.make_head.bind(grid);
    grid.make_head = function () {
        const result = original_make_head();
        bind_order_lines_gear(grid);
        return result;
    };

    bind_order_lines_gear(grid);
    apply_order_lines_column_visibility(grid, get_shown_order_lines_columns());
}

function bind_order_lines_gear(grid) {
    const $gear = $(grid.wrapper).find(".grid-heading-row .grid-static-col.pointer");
    if (!$gear.length) return;

    // Retarget the native gear click: open our dropdown instead of Frappe's
    // own "Configure Columns" modal dialog. `.off("click")` (not just a
    // namespaced unbind) is required here - Frappe's own handler is bound
    // unnamespaced in add_column_configure_button(), and jQuery fires
    // same-element handlers in registration order, so an un-namespaced
    // handler bound first would still fire the native dialog before a
    // merely-namespaced handler added afterward gets a turn to call
    // stopImmediatePropagation.
    $gear.off("click").on("click.so_col_picker", function (e) {
        e.preventDefault();
        toggle_order_lines_column_dropdown($gear, grid);
        return false;
    });
}

function toggle_order_lines_column_dropdown($gear, grid) {
    let $dd = $("#so-col-dd");
    if ($dd.length) {
        $dd.remove();
        return;
    }

    const shown = new Set(get_shown_order_lines_columns());
    const rows_html = ORDER_LINES_OPTIONAL_COLUMNS.map((col) => {
        const checked = shown.has(col.fieldname) ? "checked" : "";
        return `<label class="so-col-opt">
                <input type="checkbox" data-fieldname="${col.fieldname}" ${checked}>
                <span>${__(col.label)}</span>
            </label>`;
    }).join("");

    $dd = $(`<div id="so-col-dd" class="is-open">${rows_html}</div>`);
    // Appended to <body>, not inside the gear cell - see the `position:fixed`
    // comment on the stylesheet above for why. Right-aligned under the gear,
    // same visual spot the old nested-absolute version aimed for.
    $("body").append($dd);
    const gear_box = $gear[0].getBoundingClientRect();
    $dd.css({ top: gear_box.bottom + 4, left: gear_box.right - $dd.outerWidth() });

    $dd.on("click", (e) => e.stopPropagation());
    $dd.on("change", "input[type=checkbox]", function () {
        const fieldname = $(this).data("fieldname");
        const is_checked = $(this).is(":checked");
        const shown_cols = get_shown_order_lines_columns().filter((f) => f !== fieldname);
        if (is_checked) shown_cols.push(fieldname);
        save_shown_order_lines_columns(shown_cols);
        apply_order_lines_column_visibility(grid, shown_cols);
    });

    $(document).off("click.so_col_dd").on("click.so_col_dd", function () {
        $dd.remove();
    });
}
